6	namespace seed_b_backend.Api.Services;
7	
8	public class ProductQueryService(AppDbContext db)
9	{
10	    private const int PageSize = 20;
11	
12	    public async Task<PagedResultDto<ProductListItemDto>> GetProductsAsync(int page, string? categoryId = null, string? subcategoryId = null, string? sortBy = null, string? sortDirection = null)
13	    {
14	        page = page < 1 ? 1 : page;
15	
16	        IQueryable<Product> query = db.Products.Include(p => p.Subcategory);
17	
18	        if (!string.IsNullOrEmpty(subcategoryId))
19	        {
20	            query = query.Where(p => p.SubcategoryId == subcategoryId);
21	        }
22	        else if (!string.IsNullOrEmpty(categoryId))
23	        {
24	            query = query.Where(p => p.Subcategory!.CategoryId == categoryId);
25	        }
26	
27	        var totalCount = await query.CountAsync();
28	
29	        // long arithmetic + clamp to totalCount avoids an int overflow into a negative
30	        // Skip() for very large page values while preserving "beyond last page -> empty" behavior.
31	        var skip = (int)Math.Min((long)(page - 1) * PageSize, totalCount);
32	
33	        var descending = sortDirection == "desc";
34	        IOrderedQueryable<Product> orderedQuery = sortBy == "price"
35	            ? (descending
36	                ? query.OrderByDescending(p => p.Offers.Min(o => o.Price))
37	                : query.OrderBy(p => p.Offers.Min(o => o.Price)))
38	            : (descending
39	                ? query.OrderByDescending(p => p.Name.ToLower())
40	                : query.OrderBy(p => p.Name.ToLower()));
41	
42	        var items = await orderedQuery
43	            .ThenBy(p => p.Id)
44	            .Skip(skip)
45	            .Take(PageSize)
46	            .Select(p => new ProductListItemDto(
47	                p.Id,
48	                p.Name,
49	                p.Subcategory!.Name,
50	                p.Offers.Min(o => o.Price)))
51	            .ToListAsync();
52	
53	        var totalPages = (int)Math.Ceiling(totalCount / (double)PageSize);
54	
55	        return new PagedResultDto<ProductListItemDto>(items, page, PageSize, totalCount, totalPages);
56	    }
57	}
